func (u *PedidoUpsertBulk) Update(set func(*PedidoUpsert)) *PedidoUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&PedidoUpsert{UpdateSet: update})
	}))
	return u
}

